 if(remaining>.25f){B(p,type==3?"Van cargo side":"Rear door lower skin",new Vector3(side*w*.49f,type==3?(H+.95f)*.5f:.87f,(rearStart+cb)*.5f),new Vector3(.07f,type==3?H-.95f:.36f,remaining),paint);if(type!=3)B(p,"Rear side window",new Vector3(side*w*.455f,(H+1.02f)*.5f,(rearStart+cb)*.5f),new Vector3(.035f,windowHeight*.9f,remaining*.87f),glass);}
 foreach(float z in new[]{front+.78f,back-.76f}){var tyre=B(p,"Perished partly flat tyre",new Vector3(side*(w*.5f+.015f),.31f,z),new Vector3(seed%4==0?.48f:.62f,.13f,.62f),rubber,PrimitiveType.Cylinder);tyre.localRotation=Quaternion.Euler(0,0,90);var hub=B(p,"Rusty pressed wheel rim",new Vector3(side*(w*.5f+.15f),.31f,z),new Vector3(.31f,.018f,.31f),steel,PrimitiveType.Cylinder);hub.localRotation=Quaternion.Euler(0,0,90);}
