 var original=SceneManager.GetActiveScene();const string path="Assets/Scenes/3D/RecoilPrototype.unity";var s=SceneManager.GetSceneByPath(path);bool opened=!s.isLoaded;if(opened)s=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);try{SceneManager.SetActiveScene(s);Directory.CreateDirectory("Backups/ForecourtApproach");EditorSceneManager.SaveScene(s,"Backups/ForecourtApproach/"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);var all=All<Transform>(s);var world=All<RecoilPrototype>(s).Single();var old=world.transform.Find(Marker);bool first=!old;if(old)Object.DestroyImmediate(old.gameObject);var g=G(world.transform,Marker,Vector3.zero);
 var spawn=all.First(t=>t.name=="Player Spawn");var car=all.First(t=>t.name=="Parked car");var opening=all.First(t=>t.name=="Opening - roadside service station");var road=all.First(t=>t.name=="Road - foreground to misty horizon");var land=all.First(t=>t.name=="Countryside - low hills woods and mining settlement");
