 for(int i=0;i<15;i++){var stain=B(g,"Old oil and accumulated roadside dirt",new Vector3(-83+i*1.8f,.003f,i%2==0?2.5f:-2.5f),new Vector3(.4f+i%4*.23f,.004f,.3f+i%3*.17f),earth,PrimitiveType.Sphere);stain.localRotation=Quaternion.Euler(0,i*31,0);}
